import sys

MOD = 1_000_000_007


def fib(n):
    # fast doubling: a = F(k), b = F(k+1)
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * ((2 * b - a) % MOD) % MOD   # F(2k)
        d = (a * a + b * b) % MOD           # F(2k+1)
        if bit == '1':
            a, b = d, (c + d) % MOD
        else:
            a, b = c, d
    return a


def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if s:
            out.append(str(fib(int(s))))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()

import sys

MOD = 1_000_000_007


def fib(n):
    a, b = 0, 1
    for i in range(n.bit_length() - 1, -1, -1):
        c = a * (2 * b - a) % MOD
        d = (a * a + b * b) % MOD
        if (n >> i) & 1:
            a = d
            b = (c + d) % MOD
        else:
            a = c
            b = d
    return a


def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if s:
            out.append(str(fib(int(s))))
    if out:
        sys.stdout.write("\n".join(out) + "\n")


main()
